import{_ as e,o as i,c as l,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2019-09-02 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-09-02 :: Ceph Orchestration Meeting","date":"2019-09-02T00:00:00.000Z","updated":"2019-09-07T00:00:00.000Z","tags":["Ceph","OSD替换","驱动器组","Cubanetosca","测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-09-02_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-09-02_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-09-02_-_-_Ceph_Orchestration_Meeting.md"};function o(s,t,n,p,_,u){return i(),l("div",null,[...t[0]||(t[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年8月某日</p><p><strong>参会人员</strong>： Travis（远程）、Kiki（远程）、其他与会人员</p><p><strong>会议主题</strong>： 讨论Ceph集群中OSD替换、驱动器组（Drive Group）以及Cubanetosca事件模块的测试问题。</p><p><strong>关键细节</strong>：</p><ul><li><p><strong>OSD替换</strong>：</p><ul><li>Travis提到，在之前的会议上已经讨论了替换名为“toasty”的OSD，并询问是否有人员负责此事。现在Kiki回归，可以进行讨论。</li><li>讨论了OSD替换的步骤，包括移除磁盘和创建新设备。</li><li>Travis表示，API中已经移除了replace OSD的调用，因为替换OSD的操作实际上是销毁旧OSD并创建新OSD的组合操作。</li><li>认为驱动器组（Drive Group）在OSD替换中的作用，以及是否需要持久化存储驱动器组信息。</li><li>认为驱动器组规范目前并不实用，因为它增加了复杂性，并没有带来太多实际价值。</li><li>认为需要从用户界面层面获取反馈，以确定是否需要持久化存储驱动器组信息。</li></ul></li><li><p><strong>驱动器组</strong>：</p><ul><li>讨论了驱动器组在OSD替换中的作用，以及是否需要持久化存储驱动器组信息。</li><li>认为驱动器组规范目前并不实用，因为它增加了复杂性，并没有带来太多实际价值。</li><li>认为需要从用户界面层面获取反馈，以确定是否需要持久化存储驱动器组信息。</li></ul></li><li><p><strong>Cubanetosca事件模块测试</strong>：</p><ul><li>讨论了Cubanetosca事件模块缺乏测试的问题。</li><li>了解到有一个名为Adam的开发者正在尝试为Rook和Orchestrator创建测试套件，并希望测试Cubanetosca事件模块。</li><li>认为为Cubanetosca事件模块添加测试套件是一个好主意。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>继续讨论OSD替换和驱动器组规范，并从用户界面层面获取反馈。</li><li>跟进Cubanetosca事件模块的测试工作。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Kiki将参加9月6日的任务板会议，并讨论驱动器组规范和OSD替换的问题。</li><li>与Adam联系，了解Cubanetosca事件模块测试的进展情况。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些Ceph相关的英文关键词，如OSD、Drive Group、Cubanetosca等。</li><li>会议中涉及了一些技术细节，可能需要具备一定的Ceph知识才能理解。</li></ul>',12)])])}const h=e(r,[["render",o]]);export{g as __pageData,h as default};
